question:
What does the following C code print?

int i;
for (i = 0; i < 5; i++);
printf("%d", i);

What does the following C code print?

char str[] = "hello";
printf("%d %d", (int)sizeof(str), (int)strlen(str));

What does the following C code print?

int x = 2;
switch (x) {
  case 1: printf("A");
  case 2: printf("B");
  case 3: printf("C"); break;
  default: printf("D");
}

What does the following Java code print?

int x = 7;
System.out.println(x++ + ++x);

What does the following Perl code print?

my @a = (10, 20, 30);
